parameters.text:
=Thank you for your order!

Order ID: #{{ $json.body.orderId.slice(-6).toUpperCase() }}
Total: ${{ ($json.body.total / 100).toFixed(2) }}
Payment Method: {{ $json.body.paymentMethod }}
Pickup Slot: {{ $json.body.pickupSlot || 'Farmstand Walk-up' }}

We look forward to baking for you!

parameters.jsonBody:
={
  "phone": "{{ $json.body.customerPhone }}",
  "message": "{{ $json.body.businessName }}: Your order #{{ $json.body.orderId.slice(-6).toUpperCase() }} is confirmed! Pickup: {{ $json.body.pickupSlot || 'Farmstand' }}. Thank you!"
}
